#!/usr/bin/env python3
"""Fixture generator for the cistern-loom task.

Builds a self-authored TypeScript repository ("textreel", a rule-based text
annotation engine, more than 5,000 source lines) at a target directory, then
creates a git history for it with incremental commits. The task that ships in
this wave asks an agent to migrate the repository from non-strict TypeScript
to ``strict: true`` + ``strictNullChecks: true`` while keeping the vitest
suite green.

Everything below is authored for this benchmark: the library model, the
tokenizer, the rule engine, the config parser, the tests and the docs. No
upstream source is vendored.

Deterministic: given a target directory it writes identical file bytes every
run (git commit timestamps differ, which is intended).
"""

import os
import re
import subprocess
import sys
import json

OUT = sys.argv[1] if len(sys.argv) > 1 else "/tmp/leda-repo"


def write(rel, text):
    path = os.path.join(OUT, rel)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(text)


BANNED = [
    (r"\bany\b", "word 'any'"),
    (r"@ts-ignore", "@ts-ignore"),
    (r"@ts-expect-error", "@ts-expect-error"),
    (r"\bas\b", "word 'as'"),
    (r"\w!\s*[^=]", "suspicious '!' (non-null assertion)"),
    (r"[)\]]!\s*[^=]", "suspicious '!' (non-null assertion)"),
]


def check_clean(rel, text):
    for pat, what in BANNED:
        for m in re.finditer(pat, text):
            line = text.count("\n", 0, m.start()) + 1
            raise SystemExit(
                "GEN ERROR: %s:%d contains %s: %r"
                % (rel, line, what, text[max(0, m.start() - 40):m.end() + 20])
            )


def w(rel, text):
    check_clean(rel, text)
    write(rel, text)




