def emit_all():
    for rel, text in SCAFFOLD_FILES:
        w(rel, text)
    for rel, text in MODULE_FILES:
        w(rel, text)
    for name, text in TESTS_FILES:
        w("tests/" + name, text)
    src_lines = 0
    src_files = 0
    for rel, _ in MODULE_FILES:
        if rel.endswith(".ts") and rel.startswith("src/"):
            with open(os.path.join(OUT, rel), encoding="utf-8") as fh:
                src_lines += sum(1 for _ in fh)
            src_files += 1
    test_lines = 0
    for name, _ in TESTS_FILES:
        with open(os.path.join(OUT, "tests", name), encoding="utf-8") as fh:
            test_lines += sum(1 for _ in fh)
    manifest = {
        "src_files": src_files,
        "src_lines": src_lines,
        "test_files": len(TESTS_FILES),
        "test_lines": test_lines,
    }
    with open(os.path.join(OUT, "fixture-manifest.json"), "w", encoding="utf-8") as fh:
        json.dump(manifest, fh, indent=2)
    return manifest


def git(*args):
    subprocess.run(["git", "-C", OUT] + list(args), check=True, capture_output=True)


def build_history():
    if os.path.isdir(os.path.join(OUT, ".git")):
        subprocess.run(["rm", "-rf", os.path.join(OUT, ".git")], check=True)
    git("init", "-b", "main")
    git("config", "user.name", "build")
    git("config", "user.email", "build@localhost")
    for scaf in ["package.json", "tsconfig.json", ".gitignore",
                 "vitest.config.ts", "README.md", "CHANGELOG.md", "docs"]:
        git("add", scaf)
    git("commit", "-q", "-m", "chore: project scaffold")
    commit_pairs = []
